/**
 * Brand identity (Enterprise Brand Identity, Figma "06 / Brand Guidelines"):
 * one symbol, one wordmark, Inter. Blue on white is 5.99:1 and navy on white
 * 14.6:1 (WCAG AA for body text); use sky on dark surfaces, never blue on navy.
 * Raster assets are regenerated by tools/brand/generate.mjs.
 */
export const BRAND = {
  name: "Remote AI Platform",
  tagline: "Connect. Find work. Get work done.",
  blue: "#175CD3",
  blueHover: "#124BAD",
  navy: "#102A43",
  charcoal: "#1F2937",
  mist: "#F5F8FC",
  sky: "#8DBBFF",
  dark: "#101820",
} as const;

/** schema.org Organization for the operator of the site (home page). */
export function organizationJsonLd(siteUrl: string, contactEmail?: string | null) {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": `${siteUrl}/#organization`,
    name: BRAND.name,
    url: `${siteUrl}/`,
    logo: { "@type": "ImageObject", url: `${siteUrl}/icons/icon-512.png`, width: 512, height: 512 },
    ...(contactEmail
      ? { contactPoint: { "@type": "ContactPoint", contactType: "customer support", email: contactEmail } }
      : {}),
  };
}

/** schema.org WebSite (the site name Google shows in results). */
export function websiteJsonLd(siteUrl: string) {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    "@id": `${siteUrl}/#website`,
    name: BRAND.name,
    url: `${siteUrl}/`,
    publisher: { "@id": `${siteUrl}/#organization` },
    inLanguage: "en",
  };
}

/** schema.org BreadcrumbList from [name, path] pairs. */
export function breadcrumbJsonLd(siteUrl: string, trail: [string, string][]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: trail.map(([name, path], i) => ({
      "@type": "ListItem",
      position: i + 1,
      name,
      item: `${siteUrl}${path}`,
    })),
  };
}
